// ── Parse form inputs ──────────────────────────────────────────
const raw_url   = $input.first().json['YouTube Channel URL'] || '';
const name      = ($input.first().json['Channel Name (label)'] || '').trim();
const limit_raw = $input.first().json['Max Videos Per Day'];
const backfill_str = $input.first().json['Download Full History (Backfill)'] || '';

const daily_limit   = parseInt(limit_raw, 10) || 10;
const do_backfill   = backfill_str.toLowerCase().includes('yes');
const url           = raw_url.trim();

if (!url || !name) {
  throw new Error('Channel URL and Channel Name are required.');
}

// ── Extract channel key from URL ────────────────────────────────
// Priority: /channel/UCxxxxx > @handle > full URL as fallback
let channel_key = url;

const uc_match = url.match(/\/channel\/(UC[\w-]{10,})/);
if (uc_match) {
  channel_key = uc_match[1];
} else {
  const handle_match = url.match(/\/@([^/?#]+)/);
  if (handle_match) {
    channel_key = handle_match[1];  // e.g. "MrBeast"
  }
}

// ── Build the channel entry ──────────────────────────────────────
const today = new Date().toISOString().split('T')[0];
const entry = {
  name:                name,
  url:                 url,
  auto_download:       true,
  daily_upload_limit:  daily_limit,
  backfill_complete:   !do_backfill,
  backfill_queue:      [],
  backfill_entry_map:  {},
  uploads_today:       0,
  uploads_today_date:  today,
  videos_seen:         [],
  last_check:          new Date(0).toISOString()
};

return [{ json: { channel_key, entry, name, url, daily_limit, do_backfill } }];

const parsed = $('Parse & Build Entry').first().json;
let config = { channels: {} };

try {
  const fileItem = $('Read Config File').first();
  if (fileItem.binary && fileItem.binary.data) {
    const text = Buffer.from(fileItem.binary.data.data, 'base64').toString('utf-8');
    config = JSON.parse(text.trim());
  }
} catch(e) {
  config = { channels: {} };
}
if (!config.channels) config.channels = {};

const key   = parsed.channel_key;
const entry = parsed.entry;

if (config.channels[key]) {
  entry.videos_seen        = config.channels[key].videos_seen || [];
  entry.uploads_today      = config.channels[key].uploads_today || 0;
  entry.uploads_today_date = config.channels[key].uploads_today_date || entry.uploads_today_date;
  if (!parsed.do_backfill) {
    entry.backfill_complete  = config.channels[key].backfill_complete;
    entry.backfill_queue     = config.channels[key].backfill_queue || [];
    entry.backfill_entry_map = config.channels[key].backfill_entry_map || {};
  }
}

config.channels[key] = entry;

const jsonStr = JSON.stringify(config, null, 2);
const mode    = parsed.do_backfill ? 'BACKFILL (full history)' : 'MONITOR only';
const message = 'Channel "' + parsed.name + '" added!\nKey: ' + key + '\nMode: ' + mode + '\nDaily limit: ' + parsed.daily_limit + ' videos/day\nThe watcher will pick this up on its next poll cycle.';

return [{
  json: { message, channel_key: key, name: parsed.name },
  binary: {
    data: {
      data:     Buffer.from(jsonStr).toString('base64'),
      mimeType: 'application/json',
      fileName: 'channel_monitor_config.json'
    }
  }
}];
